  const node=root(),record={invoiceId:'15',documentNo:'F15',customerId:'2',customerName:'Deneme',documentDate:'2026-11-09',workflowState:'COMPLETED',version:'0x0000000000000015',currency:'TRY',totalExact4:'24.0000',items:[],cartonItems:[],...staff};let reads=0;
  const screen=mountDesktopWorkflowScreen({root:node,actorId:'30002',storage:{getItem:k=>k.includes('.last.')?'15':null,setItem(){throw Error('read persisted selection');},removeItem(){throw Error('read removed pending');}},core:{sale:()=>({pending:()=>null,read:async id=>{assert.equal(id,'15');reads++;return record;}}),customerCard:()=>{throw Error('directory lookup');},companyRates:()=>{throw Error('rate lookup');}}});await new Promise(r=>setImmediate(r));
