async function dueScreenFixture({minimal=false,chooseOwn=false,boss}={}){
 const node=root(),tick=()=>new Promise(r=>setImmediate(r)),calls=[],writes=[],requests=[];let unknown=false,denied=false;
 const record={invoiceId:'5',customerId:'2',customerName:'Deneme',documentNo:'TEST-5',documentDate:'2026-11-09',workflowState:'CHECKED',version:'0x0000000000000001',totalExact4:'10.0000',items:[{itemId:'1',productId:'9',stockCode:'P9',name:'Bir',quantityExact3:'1.000',unitPriceExact4:'5.0000',lineTotalExact4:'5.0000'},{itemId:'2',productId:'10',stockCode:'P10',name:'İki',quantityExact3:'1.000',unitPriceExact4:'5.0000',lineTotalExact4:'5.0000'}],cartonItems:[]};
 const context={invoiceId:'5',expectedVersion:record.version,customerId:'2',accountId:'7',currency:'TRY',documentDate:record.documentDate,amountExact4:'10.0000',termsDefinition:null},snapshot={...context,requestedTermDays:30,requestedDueDate:'2026-12-09'},rows=[{id:'31',actorId:chooseOwn?'8':'9',snapshot,reason:'Fişe özel süre',status:minimal?'PENDING':'APPROVED',expiresAt:Date.now()+600000}];
 const credit={pending:()=>unknown?{exists:true}:null,readDueInvoice:async(...args)=>{calls.push(args);return structuredClone(context);},listDueRequests:async()=>{if(denied)throw Error('Erişim reddedildi');return {requests:rows,limited:true,canApprove:minimal||boss!==undefined};},createDueRequest:async fields=>{requests.push(fields);unknown=true;return {state:'UNKNOWN'};},approveDue:async fields=>{writes.push(fields);return {state:'UNKNOWN'};},resolve:async()=>({state:'UNKNOWN'})};
 const screen=mountDesktopWorkflowScreen({root:node,actorId:'8',storage:{getItem:k=>!minimal&&k.includes('.last.')?'5':null,setItem(){},removeItem(){}},core:{...(minimal?{can:k=>k==='sales',getUser:()=>({permissions:['sales.view']})}:{}),...(boss===undefined?{}:{salesApprovals:()=>({pending:()=>null,canApprove:()=>true,list:async()=>({salesPolicy:{version:1,actorId:'8',revision:'b'.repeat(64),canChangeSalePrice:false,maxDiscountRateExact4:'0.0000',canApproveUpToFive:true,canApproveAboveFive:boss},requests:[]})})}),credit:()=>credit,sale:()=>({pending:()=>null,read:async()=>structuredClone(record),create:async(kind,body)=>{writes.push({kind,body});return {state:'UNKNOWN'};}}),list:async()=>{throw Error('No catalog access');}}});await tick();
 return {node,tick,calls,writes,requests,rows,context,screen,deny(){denied=true;},input(selector,value){const f=node.querySelector(selector);f.value=value;f.events.input({target:f});}};
}
