 const screen=mountDesktopWorkflowScreen({root:node,core:{sale:()=>({pending:()=>null}),salesApprovals:()=>approvals,list:async()=>({data:[],meta:{hasNextPage:false}})},storage:{getItem:()=>null,setItem(){},removeItem(){}},actorId:'8'}),tick=()=>new Promise(r=>setImmediate(r));
 await tick();node.querySelector('[data-approvals]').events.click();await tick();assert.deepEqual(node.querySelectorAll('[data-approval-approve]').map(x=>x.dataset.approvalApprove),['12','13']);
 const stale=node.querySelector('[data-approval-approve="13"]');allowed=false;stale.events.click();await tick();assert.equal(posts,0);assert.match(node.innerHTML,/Onay yetkiniz yok/);listDenied=true;node.querySelector('[data-approval-refresh]').events.click();await tick();assert.equal(node.querySelectorAll('[data-approval-approve]').length,0);assert.doesNotMatch(node.innerHTML,/İstek #12/);screen.dispose();
