test('one selected sale slot compacts preview quantities and pricing without reading the empty slot, then saves that same line',async()=>{
 for(const slot of [0,1]){
  const node=root(),previews=[],writes=[],policy={version:1,actorId:'8',revision:'b'.repeat(64),canChangeSalePrice:true,maxDiscountRateExact4:'5.0000',canApproveAboveFive:false};
  const controller={pending:()=>null,preview:async input=>{previews.push(structuredClone(input));const unitPriceExact4=input.pricing.unitPricesExact4[0]??'12.0000',total=(Number(input.quantities[0])*Number(unitPriceExact4)).toFixed(4);return {revision:'a'.repeat(64),salesPolicy:policy,products:[{productId:'10',stockCode:'P10',unit:'ADET',priceExact4:'12.0000',stockExact3:'10.000',reservedExact3:'0.000'}],quote:{currency:'TRY',lines:[{productId:'10',quantityExact3:input.quantities[0],unitPriceExact4,lineTotalExact4:total}],subtotalExact4:total,discountRateExact4:'0.0000',discountTotalExact4:'0.0000',totalExact4:total,maxDiscountRateExact4:'5.0000',approvalRequired:false,writeSupported:true,belowCostWarning:false}}},create:async(kind,body)=>{writes.push({kind,body});return {state:'UNKNOWN'}}};
  const screen=mountDesktopWorkflowScreen({root:node,storage:{getItem:()=>null,setItem(){},removeItem(){}},actorId:'8',core:{sale:()=>controller,salesApprovals:()=>({pending:()=>null,list:async()=>({salesPolicy:policy,requests:[]})}),list:async kind=>({data:kind==='customers'?[{id:'2',customerCode:'C2',customerName:'Deneme'}]:[{id:'10',stockCode:'P10',productName:'Tek ürün',unit:'ADET'}],meta:{hasNextPage:false}})}});
  await new Promise(r=>setImmediate(r));node.querySelector('[data-customer]').events.change({target:{value:'2'}});node.querySelector('[data-product="'+slot+'"]').events.change({target:{value:'10',dataset:{product:String(slot)}}});
  const quantity=node.querySelector('[data-quantity="'+slot+'"]');quantity.events.input({target:{value:'2',dataset:{quantity:String(slot)}}});const emptySlot=1-slot;node.querySelector('[data-quantity="'+emptySlot+'"]').events.input({target:{value:'invalid unused quantity',dataset:{quantity:String(emptySlot)}}});
  await node.querySelector('[data-preview]').events.click();assert.deepEqual(previews[0].productIds,['10']);assert.deepEqual(previews[0].quantities,['2.000']);assert.deepEqual(previews[0].quantityUnits,['ADET']);assert.deepEqual(previews[0].pricing.unitPricesExact4,[null]);assert.match(node.innerHTML,/Toplam: 24.0000 TRY/);assert.equal(node.querySelector('[data-draft]').disabled,false);
  const priceField=node.querySelector('[data-sale-price="'+slot+'"]');assert.ok(priceField);priceField.events.input({target:{value:'11,5',dataset:{salePrice:String(slot)}}});assert.equal(node.querySelector('[data-draft]').disabled,true);await node.querySelector('[data-preview]').events.click();assert.deepEqual(previews[1].pricing.unitPricesExact4,['11.5000']);assert.match(node.innerHTML,/Toplam: 23.0000 TRY/);assert.equal(node.querySelector('[data-draft]').disabled,false);await node.querySelector('[data-draft]').events.click();assert.equal(writes.length,1);assert.deepEqual(writes[0].body.items,[{productId:'10',quantityExact3:'2.000'}]);assert.deepEqual(writes[0].body.pricing.unitPricesExact4,['11.5000']);screen.dispose();
 }
});

test('empty or duplicate product selection has a clear local message and makes no preview or write request',async()=>{
 const f=await barcodeFixture();await f.node.querySelector('[data-preview]').events.click();assert.match(f.node.innerHTML,/en az bir ürün seçin/);assert.equal(f.previews.length,0);for(const slot of [0,1])f.node.querySelector('[data-product="'+slot+'"]').events.change({target:{value:'10',dataset:{product:String(slot)}}});await f.node.querySelector('[data-preview]').events.click();assert.match(f.node.innerHTML,/Aynı ürünü iki satırda seçmeyin/);assert.equal(f.previews.length,0);assert.equal(f.writes.length,0);f.screen.dispose();
});


test('a second-slot singleton series uses its matching authoritative preview factor for display and draft',async()=>{
 const node=root(),calls=[],controller={pending:()=>null,preview:async input=>pricedPreview(input,{revision:'a'.repeat(64),products:[{productId:'5',stockCode:'P5',unit:'ADET',priceExact4:'12.0000',stockExact3:'60.000',reservedExact3:'0.000',seriesUnit:{unitId:'53',factorExact8:'8.00000000'}}]}),create:async(kind,body)=>{calls.push({kind,body});return {state:'UNKNOWN'}}},core={sale:()=>controller,list:async kind=>({data:kind==='customers'?[{id:'2',customerCode:'C2',customerName:'Deneme'}]:[{id:'5',stockCode:'P5',productName:'Serili tek ürün',unit:'ADET',seriesUnitId:'53',seriesFactorExact8:'6.00000000'}],meta:{hasNextPage:false}})};
 const v=mountDesktopWorkflowScreen({root:node,core,storage:{getItem:()=>null,setItem(){},removeItem(){}},actorId:'8'});await new Promise(r=>setImmediate(r));node.querySelector('[data-customer]').events.change({target:{value:'2'}});node.querySelector('[data-product="1"]').events.change({target:{value:'5',dataset:{product:'1'}}});node.querySelector('[data-quantity-unit="1"]').events.change({target:{value:'SERİ',dataset:{quantityUnit:'1'}}});node.querySelector('[data-quantity="1"]').events.input({target:{value:'2',dataset:{quantity:'1'}}});await node.querySelector('[data-preview]').events.click();assert.match(node.innerHTML,/2.000 SERİ = 16.000 ADET/);assert.equal(node.querySelector('[data-draft]').disabled,false);await node.querySelector('[data-draft]').events.click();assert.equal(calls.length,1);assert.deepEqual(calls[0].body.items,[{productId:'5',quantityExact3:'16.000',series:{unitId:'53',factorExact8:'8.00000000',quantityExact3:'2.000'}}]);v.dispose();
});

test('using an approved one-line sale restores an empty second UI slot and keeps exact approval pricing on save',async()=>{
 const node=root(),writes=[],previews=[],policy={version:1,actorId:'8',revision:'b'.repeat(64),canChangeSalePrice:true,maxDiscountRateExact4:'5.0000',canApproveAboveFive:true},d={customerId:'2',documentDate:'2026-11-11',expectedRevision:'a'.repeat(64),items:[{productId:'8',quantityExact3:'1.000'}],discountRateExact4:'6.0000',pricing:{version:1,policyRevision:'b'.repeat(64),unitPricesExact4:[null],approvalId:null}},quote={currency:'TRY',lines:[{productId:'8',quantityExact3:'1.000',unitPriceExact4:'10.0000',lineTotalExact4:'10.0000'}],subtotalExact4:'10.0000',discountRateExact4:'6.0000',discountTotalExact4:'0.6000',totalExact4:'9.4000',belowCostWarning:false},row={id:'12',actorId:'8',status:'APPROVED',approvalId:'99',invoice:null,expiresAt:Date.now()+600000,createdAt:Date.now(),decision:{actorId:'8',reason:'Uygun',decidedAt:Date.now()},draft:d,quote,customerId:'2',documentDate:d.documentDate,discountRateExact4:d.discountRateExact4,items:d.items,unitPricesExact4:[null]};
 const approvals={pending:()=>null,list:async()=>({salesPolicy:policy,requests:[row]}),canApprove:()=>true},controller={pending:()=>null,preview:async input=>{previews.push(structuredClone(input));return {revision:d.expectedRevision,salesPolicy:policy,products:[{productId:'8',stockCode:'P8',unit:'ADET',priceExact4:'10.0000',stockExact3:'20.000',reservedExact3:'0.000'}],quote:{...quote,maxDiscountRateExact4:'5.0000',approvalRequired:false,writeSupported:true}}},create:async(kind,body)=>{writes.push({kind,body});return {state:'UNKNOWN'}}},core={sale:()=>controller,salesApprovals:()=>approvals,list:async kind=>({data:kind==='customers'?[{id:'2',customerCode:'C2',customerName:'Deneme'}]:[{id:'8',stockCode:'P8',productName:'Tek ürün',unit:'ADET'}],meta:{hasNextPage:false}})};
 const v=mountDesktopWorkflowScreen({root:node,core,storage:{getItem:()=>null,setItem(){},removeItem(){}},actorId:'8'});await new Promise(r=>setImmediate(r));await node.querySelector('[data-approvals]').events.click();node.querySelector('[data-approval-use="12"]').events.click();assert.ok(node.querySelector('[data-product="1"]'));assert.equal(node.querySelector('[data-quantity="1"]').value,'1.000');await node.querySelector('[data-preview]').events.click();assert.deepEqual(previews[0].productIds,['8']);assert.deepEqual(previews[0].pricing.unitPricesExact4,[null]);assert.equal(previews[0].pricing.approvalId,'99');assert.equal(node.querySelector('[data-draft]').disabled,false);await node.querySelector('[data-draft]').events.click();assert.equal(writes.length,1);assert.deepEqual(writes[0].body.items,d.items);assert.equal(writes[0].body.pricing.approvalId,'99');v.dispose();
});


test('a saved single-line receipt packs, reaches checked, dispatches its one product and reopens unchanged',async()=>{
 const node=root(),calls=[],saved=new Map([['melisa.desktop.workflow.last.v1.8','15']]),storage={getItem:k=>saved.get(k)??null,setItem:(k,v)=>saved.set(k,v),removeItem:k=>saved.delete(k)};let step=1,record={invoiceId:'15',customerId:'2',customerName:'Deneme',documentNo:'ONE-15',documentDate:'2026-11-11',workflowState:'PREPARING',version:'0x0000000000000001',totalExact4:'12.0000',items:[{itemId:'1',productId:'9',stockCode:'ONE',name:'Tek ürün',quantityExact3:'1.000',unitPriceExact4:'12.0000',lineTotalExact4:'12.0000'}],cartonItems:[]};
 const controller={pending:()=>null,read:async()=>structuredClone(record),create:async(kind,body)=>{calls.push({kind,body:structuredClone(body)});if(kind==='transition'){record={...record,workflowState:{SAVE_CARTONS:'PREPARING',READY:'READY',CHECK:'CHECKED'}[body.operation]};if(body.operation==='SAVE_CARTONS')record.cartonItems=body.cartons.flatMap(b=>b.items.map(i=>({...i,cartonNo:b.cartonNo,productId:'9'})));}else if(kind==='dispatch')record={...record,workflowState:'COMPLETED'};record.version='0x'+String(++step).padStart(16,'0');return {state:'COMMITTED',requestId:'da171000-6f42-4f19-8cab-9f4539618647',invoiceId:'15',workflowState:record.workflowState,version:record.version,replayed:false};}};
 const core={sale:()=>controller},v=mountDesktopWorkflowScreen({root:node,core,storage,actorId:'8'});await new Promise(r=>setImmediate(r));node.querySelector('[data-add-box]').events.click();const field=node.querySelector('[data-box="0"]');field.events.input({target:{value:'1',dataset:{box:'0',item:'1'}}});await node.querySelector('[data-save-boxes]').events.click();await node.querySelector('[data-action="READY"]').events.click();await node.querySelector('[data-action="CHECK"]').events.click();node.querySelector('[data-confirm]').events.click();await node.querySelector('[data-dispatch]').events.click();assert.equal(record.workflowState,'COMPLETED');assert.match(node.innerHTML,/ONE-15/);assert.match(node.innerHTML,/Tamamlandı/);assert.equal(calls.length,4);assert.deepEqual(calls[0].body.cartons,[{cartonNo:1,items:[{itemId:'1',quantityExact3:'1.000'}]}]);assert.deepEqual(calls[3].body.productIds,['9']);v.dispose();
 const reopened=mountDesktopWorkflowScreen({root:node,core,storage,actorId:'8'});await new Promise(r=>setImmediate(r));assert.match(node.innerHTML,/ONE-15/);assert.match(node.innerHTML,/Tamamlandı/);assert.match(node.innerHTML,/12.0000 TRY/);assert.equal(calls.length,4);reopened.dispose();
});
